int read_and_process_gif_image(struct iwgifrcontext *rctx) {
    // Read image header
    unsigned char header[6];
    if (fread(header, 1, 6, rctx->file) != 6) {
        return 0;
    }

    // Parse image header for width, height, and interlacing
    rctx->width = (header[0] << 8) | header[1];
    rctx->height = (header[2] << 8) | header[3];
    rctx->interlaced = (header[4] & 0x40) ? 1 : 0;

    // Validate image dimensions
    if (rctx->width == 0 || rctx->height == 0) {
        return 0;
    }

    // Determine if a local color table is present
    int local_color_table = header[4] & 0x80 ? 1 : 0;
    int color_table_size = 1 << ((header[4] & 0x07) + 1);

    if (local_color_table) {
        rctx->color_table = (unsigned char*)malloc(3 * color_table_size);
        if (rctx->color_table == NULL) {
            return 0;
        }

        if (fread(rctx->color_table, 3, color_table_size, rctx->file) != color_table_size) {
            free(rctx->color_table);
            return 0;
        }

        // Handle transparency if specified
        if (header[5] == 0x01) {
            rctx->transparent_index = header[5];
            rctx->color_table[rctx->transparent_index * 3 + 3] = 0; // Assuming alpha channel
        }
    }

    // Read LZW code size
    rctx->lzw_code_size = fgetc(rctx->file);
    if (rctx->lzw_code_size < 2 || rctx->lzw_code_size > 12) {
        return 0;
    }

    // Initialize screen context for pixel data
    rctx->pixel_data = (unsigned char*)malloc(rctx->width * rctx->height);
    if (rctx->pixel_data == NULL) {
        free(rctx->color_table);
        return 0;
    }

    // Read pixel data in subblocks
    int i = 0;
    while (1) {
        unsigned char subblock_size = fgetc(rctx->file);
        if (feof(rctx->file)) {
            break;
        }

        if (subblock_size == 0) {
            break;
        }

        unsigned char subblock_data[subblock_size];
        if (fread(subblock_data, 1, subblock_size, rctx->file) != subblock_size) {
            break;
        }

        // Process subblock with LZW decoding (implementation assumed)
        process_lzw_subblock(rctx, subblock_data, subblock_size, i);
        i += subblock_size;
    }

    if (ferror(rctx->file)) {
        free(rctx->color_table);
        free(rctx->pixel_data);
        return 0;
    }

    return 1;
}

int iwgif_read_and_process_image(struct iwgifrcontext *rctx) {
    // Read image header
    uint8_t header[IWGIF_HEADER_SIZE];
    if (rctx->read_func(rctx, header, IWGIF_HEADER_SIZE) != IWGIF_HEADER_SIZE) {
        return 0;
    }

    // Parse header for dimensions and interlacing
    rctx->width = (header[0] << 8) | header[1];
    rctx->height = (header[2] << 8) | header[3];
    if (rctx->width == 0 || rctx->height == 0) {
        return 0; // Invalid dimensions
    }

    uint8_t packed = header[4];
    rctx->interlaced = (packed & 0x40) ? 1 : 0;
    rctx->has_local_palette = (packed & 0x80) ? 1 : 0;

    // Initialize local color table if present
    if (rctx->has_local_palette) {
        size_t palette_size = 1 << ((packed & 0x07) + 1);
        if (palette_size > GIF_MAX_PALETTE_SIZE || rctx->palette_size < palette_size) {
            return 0; // Palette size exceeds limits or insufficient buffer
        }

        if (rctx->read_func(rctx, rctx->palette, palette_size * 3) != palette_size * 3) {
            return 0; // Failed to read color table
        }

        rctx->palette_size = palette_size;
    }

    // Handle transparency
    if (rctx->has_local_palette && (rctx->flags & GIF_FLAG_TRANSPARENT)) {
        rctx->transparent_index = rctx->global_palette_size;
    }

    // Read LZW minimum code size
    if (rctx->read_func(rctx, &rctx->lzw_min_code_size, 1) != 1) {
        return 0;
    }

    if (rctx->lzw_min_code_size < 1 || rctx->lzw_min_code_size > 12) {
        return 0; // Invalid LZW code size
    }

    // Initialize screen context
    if (!iwgif_init_screen_context(rctx)) {
        return 0;
    }

    // Read and process subblocks
    int end_of_image = 0;
    while (!end_of_image && rctx->read_func(rctx, &rctx->subblock_size, 1) == 1) {
        if (rctx->subblock_size == 0) {
            end_of_image = 1;
            break;
        }

        uint8_t subblock[rctx->subblock_size];
        if (rctx->read_func(rctx, subblock, rctx->subblock_size) != rctx->subblock_size) {
            return 0;
        }

        if (!iwgif_process_subblock(rctx, subblock)) {
            return 0;
        }
    }

    return 1;
}

int iwgif_read_and_process_image(struct iwgifrcontext *rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    unsigned char image_header[6];
    if (fread(image_header, sizeof(unsigned char), 6, rctx->file) != 6) {
        return 0;
    }

    // Parse image header
    rctx->image.left = (image_header[0] << 8) | image_header[1];
    rctx->image.top = (image_header[2] << 8) | image_header[3];
    rctx->image.width = (image_header[4] << 8) | image_header[5];
    rctx->image.height = (image_header[5] << 8) | image_header[5]; // Adjust for correct parsing

    // Check for valid dimensions
    if (rctx->image.width <= 0 || rctx->image.height <= 0) {
        return 0;
    }

    // Parse flags and field specifiers
    unsigned char image_descriptor = image_header[5];
    rctx->image.is_interlaced = (image_descriptor & 0x40) ? 1 : 0;
    rctx->image.has_local_color_table = (image_descriptor & 0x80) ? 1 : 0;

    // Determine number of bits for color table
    int color_table_size = (image_descriptor & 0x07) + 1;

    // Initialize color table if present
    if (rctx->image.has_local_color_table) {
        unsigned char color_table_size_bytes = 3 * (1 << color_table_size);
        rctx->local_color_table = (unsigned char *)malloc(color_table_size_bytes);
        if (!rctx->local_color_table) {
            return 0;
        }

        if (fread(rctx->local_color_table, sizeof(unsigned char), color_table_size_bytes, rctx->file) != color_table_size_bytes) {
            free(rctx->local_color_table);
            rctx->local_color_table = NULL;
            return 0;
        }

        // Handle transparency
        rctx->transparent_index = image_descriptor >> 4;
        if (rctx->transparent_index < (1 << color_table_size)) {
            rctx->local_color_table[rctx->transparent_index * 3 + 3] = 0;
        }
    }

    // Read LZW code size
    unsigned char lzw_code_size;
    if (fread(&lzw_code_size, sizeof(unsigned char), 1, rctx->file) != 1) {
        if (rctx->local_color_table) {
            free(rctx->local_color_table);
        }
        return 0;
    }

    // Validate LZW code size
    if (lzw_code_size < 2 || lzw_code_size > 8) {
        if (rctx->local_color_table) {
            free(rctx->local_color_table);
        }
        return 0;
    }

    // Initialize screen context
    rctx->current_width = rctx->image.width;
    rctx->current_height = rctx->image.height;
    rctx->is_interlaced = rctx->image.is_interlaced;
    rctx->current_row = 0;

    // Read pixel data in subblocks
    unsigned char subblock_size;
    int read_complete = 0;
    while (!read_complete && !feof(rctx->file)) {
        if (fread(&subblock_size, sizeof(unsigned char), 1, rctx->file) != 1) {
            break;
        }

        if (subblock_size == 0) {
            read_complete = 1;
            break;
        }

        unsigned char *subblock_data = (unsigned char *)malloc(subblock_size);
        if (!subblock_data) {
            read_complete = 1;
            break;
        }

        if (fread(subblock_data, sizeof(unsigned char), subblock_size, rctx->file) != subblock_size) {
            free(subblock_data);
            read_complete = 1;
            break;
        }

        // Process subblock with LZW decoding
        if (!process_subblock(rctx, subblock_data, subblock_size)) {
            free(subblock_data);
            read_complete = 1;
            break;
        }

        free(subblock_data);
    }

    if (read_complete && feof(rctx->file)) {
        return 1;
    } else {
        return 0;
    }
}

int iwgif_read_image(struct iwgifrcontext *rctx) {
    uint8_t image_header[6];
    uint8_t *lzw_data = NULL;
    int ret = 0;
    int i;

    if (fread(image_header, 1, 6, rctx->fp) != 6)
        goto error;

    rctx->image.left = (image_header[0] << 8) | image_header[1];
    rctx->image.top = (image_header[2] << 8) | image_header[3];
    rctx->image.width = (image_header[4] << 8) | image_header[5];
    rctx->image.height = (image_header[4] << 8) | image_header[5];
    rctx->image.interlace = (image_header[6] >> 6) & 0x01;

    if (rctx->image.width <= 0 || rctx->image.height <= 0) {
        goto error;
    }

    rctx->local_has_table = (image_header[6] & 0x80) ? 1 : 0;
    rctx->local_color_table_size = 1 << ((image_header[6] & 0x07) + 1);

    if (rctx->local_has_table) {
        rctx->local_color_table = (struct gif_color *)malloc(rctx->local_color_table_size * sizeof(struct gif_color));
        if (!rctx->local_color_table)
            goto error;

        if (fread(rctx->local_color_table, 1, rctx->local_color_table_size * sizeof(struct gif_color), rctx->fp) != rctx->local_color_table_size * sizeof(struct gif_color)) {
            goto error;
        }

        if (image_header[6] & 0x01) {
            rctx->transparency_index = rctx->local_color_table[rctx->local_color_table_size - 1].index;
            for (i = 0; i < rctx->local_color_table_size; ++i) {
                rctx->local_color_table[i].is_transparent = (i == rctx->transparency_index) ? 1 : 0;
            }
        }
    }

    uint8_t lzw_code_size = fgetc(rctx->fp);
    if (lzw_code_size < 2 || lzw_code_size > 8)
        goto error;

    rctx->lzw_code_size = lzw_code_size;
    rctx->min_code_size = lzw_code_size;
    rctx->clear_code = (1 << lzw_code_size);
    rctx->end_of_info_code = (1 << lzw_code_size) + 1;

    lzw_data = (uint8_t *)malloc(rctx->image.width * rctx->image.height);
    if (!lzw_data)
        goto error;

    rctx->image.data = lzw_data;

    while (1) {
        uint8_t sub_block_size = fgetc(rctx->fp);
        if (feof(rctx->fp))
            goto error;

        if (sub_block_size == 0)
            break;

        uint8_t *sub_block = (uint8_t *)malloc(sub_block_size);
        if (!sub_block)
            goto error;

        if (fread(sub_block, 1, sub_block_size, rctx->fp) != sub_block_size) {
            free(sub_block);
            goto error;
        }

        if (!iwgif_decode_lzw(rctx, sub_block, sub_block_size)) {
            free(sub_block);
            goto error;
        }

        free(sub_block);
    }

    ret = 1;

error:
    if (!ret && lzw_data) {
        free(lzw_data);
    }
    return ret;
}

int read_and_process_gif_image(struct iwgifrcontext *rctx) {
    if (!rctx) {
        return 0;
    }

    // Read image header
    uint8_t header[6];
    if (fread(header, sizeof(uint8_t), 6, rctx->fp) != 6) {
        return 0;
    }

    // Extract image dimensions and interlacing info
    uint16_t width = (header[3] << 8) | header[4];
    uint16_t height = (header[5] << 8) | header[4];
    if (width == 0 || height == 0) {
        return 0;
    }

    rctx->image_width = width;
    rctx->image_height = height;
    rctx->interlaced = (header[0] & 0x40) != 0;

    // Check for local color table
    if (header[0] & 0x80) {
        uint8_t color_table_size = 1 << ((header[0] & 0x07) + 1);
        rctx->local_color_table = (uint8_t*)malloc(color_table_size * 3);
        if (!rctx->local_color_table) {
            return 0;
        }

        if (fread(rctx->local_color_table, 3, color_table_size, rctx->fp) != color_table_size) {
            free(rctx->local_color_table);
            rctx->local_color_table = NULL;
            return 0;
        }

        // Handle transparency
        if (rctx->transparent_index != -1) {
            rctx->local_color_table[rctx->transparent_index * 3 + 0] = 0;
            rctx->local_color_table[rctx->transparent_index * 3 + 1] = 0;
            rctx->local_color_table[rctx->transparent_index * 3 + 2] = 0;
        }
    }

    // Read LZW code size
    uint8_t lzw_code_size;
    if (fread(&lzw_code_size, sizeof(uint8_t), 1, rctx->fp) != 1) {
        return 0;
    }

    if (lzw_code_size < 1 || lzw_code_size > 8) {
        return 0;
    }

    rctx->lzw_code_size = lzw_code_size;

    // Initialize screen context
    rctx->current_line = 0;
    rctx->pixel_index = 0;

    // Read and process image data in subblocks
    while (!feof(rctx->fp)) {
        uint8_t subblock_size;
        if (fread(&subblock_size, sizeof(uint8_t), 1, rctx->fp) != 1) {
            break;
        }

        if (subblock_size == 0) {
            break;
        }

        uint8_t subblock[subblock_size];
        if (fread(subblock, sizeof(uint8_t), subblock_size, rctx->fp) != subblock_size) {
            return 0;
        }

        // Process subblock with LZW decoding
        if (!lzw_decode_subblock(rctx, subblock, subblock_size)) {
            return 0;
        }
    }

    return 1;
}
